namespace HelpingHands.Api.Data;

// Identifiers are generated by the API, not supplied by callers.
public sealed class Recipient
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string Reference { get; set; } = "";
    public string RecipientType { get; set; } = "Charity";
    public string DisplayName { get; set; } = "";
    public string ContactDetails { get; set; } = "";
    public string ApprovalStatus { get; set; } = "Pending";
    public bool Active { get; set; }
    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
    public Guid Version { get; set; } = Guid.NewGuid();
}

public sealed class Charity
{
    public Guid RecipientId { get; set; }
    public string? RegistrationInformation { get; set; }
}

public sealed class RecipientMember
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid RecipientId { get; set; }
    public Guid UserId { get; set; }
    public bool IsActive { get; set; } = true;
}

public sealed class RecipientDecision
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid RecipientId { get; set; }
    public Guid ActorUserId { get; set; }
    public string Decision { get; set; } = "";
    public string? Reason { get; set; }
    public DateTimeOffset DecidedAt { get; set; } = DateTimeOffset.UtcNow;
}

public sealed class ApplicationAttachment
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public Guid RecipientId { get; set; }
    public string StorageKey { get; set; } = "";
    public string OriginalName { get; set; } = "";
    public string MediaType { get; set; } = "";
    public long SizeBytes { get; set; }
    public Guid UploadedByUserId { get; set; }
    public DateTimeOffset UploadedAt { get; set; } = DateTimeOffset.UtcNow;
}
